namespace PlainApi.Evals.Tests;

internal static class Wire
{
    internal static IChatClient ResolveAgentClient() =>
        EvalEnv.UseRealAgent ? AgentChatClientFactory.Create() : new StubChatClient();

    internal static IChatClient ResolveJudgeClient(IChatClient agent)
    {
        var judgeDeployment = Environment.GetEnvironmentVariable("EVAL_JUDGE_DEPLOYMENT_NAME");
        if (string.IsNullOrEmpty(judgeDeployment))
            return agent;

        // When the judge override is set, build a separate client for the judge model.
        var builder = Host.CreateApplicationBuilder();
        builder.Configuration.AddUserSecrets(typeof(AgentChatClientFactory).Assembly, optional: true);
        // The user must wire the judge deployment in user-secrets or env vars.
        throw new NotImplementedException(
            $"EVAL_JUDGE_DEPLOYMENT_NAME={judgeDeployment} is set but no judge factory is configured. " +
            "Wire a separate IChatClient for the judge deployment.");
    }
}

namespace PlainApi.Evals.Tests;

internal static class AgentChatClientFactory
{
    /// <summary>
    /// Auto-detection failed: no IChatClient registration found in
    /// the target project. Wire your client manually.
    /// </summary>
    public static IChatClient Create() =>
        throw new NotImplementedException(
            "Wire your IChatClient here. See https://learn.microsoft.com/en-us/dotnet/ai/microsoft-extensions-ai");
}

namespace PlainApi.Evals.Tests;

/// <summary>
/// Deterministic stub that returns a fixed response for eval runs
/// without real credentials. Used when EVAL_USE_REAL_AGENT is unset.
/// </summary>
internal sealed class StubChatClient : IChatClient
{
    public Task<ChatResponse> GetResponseAsync(
        IEnumerable<ChatMessage> messages,
        ChatOptions? options = null,
        CancellationToken cancellationToken = default)
    {
        var userMessage = messages.LastOrDefault(m => m.Role == ChatRole.User)?.Text ?? "";
        var stub = $"This is a stub response for evaluation. Input was: {userMessage}";
        return Task.FromResult(new ChatResponse(new ChatMessage(ChatRole.Assistant, stub)));
    }

    public IAsyncEnumerable<ChatResponseUpdate> GetStreamingResponseAsync(
        IEnumerable<ChatMessage> messages,
        ChatOptions? options = null,
        CancellationToken cancellationToken = default) =>
        throw new NotSupportedException("Streaming not supported in stub.");

    public object? GetService(Type serviceType, object? serviceKey = null) => null;

    public void Dispose() { }
}

using System.Text.Json;

namespace PlainApi.Evals.Tests;

public record GoldenItem(string Id, string UserMessage, string? ReferenceResponse, string? Context);

internal static class GoldenLoader
{
    private static readonly JsonSerializerOptions s_options = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower,
        PropertyNameCaseInsensitive = true,
    };

