using System.Diagnostics;
using System.Text.Json;

namespace PlainApi.Evals.Tests;

public record TelemetryInput(string Agent, string Text);

internal static class InputsLoader
{
    private static readonly JsonSerializerOptions s_options = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower,
        PropertyNameCaseInsensitive = true,
    };

    public static List<TelemetryInput> Load()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "Telemetry", "inputs.json");
        return JsonSerializer.Deserialize<List<TelemetryInput>>(
            File.ReadAllText(path), s_options) ?? new();
    }
}

internal static class PriceTable
{
    private static readonly JsonSerializerOptions s_options = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower,
        PropertyNameCaseInsensitive = true,
    };

    public static Dictionary<string, PriceEntry> Load()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "Telemetry", "prices.json");
        return JsonSerializer.Deserialize<Dictionary<string, PriceEntry>>(
            File.ReadAllText(path), s_options) ?? new();
    }

    public static decimal Cost(string? model, int inputTokens, int outputTokens)
    {
        if (model is null) return 0;
        var prices = Load();
        if (!prices.TryGetValue(model, out var entry)) return 0;
        return (inputTokens / 1000m * entry.InputPer1k) + (outputTokens / 1000m * entry.OutputPer1k);
    }
}

public record PriceEntry(decimal InputPer1k, decimal OutputPer1k);

using System.Diagnostics;

namespace PlainApi.Evals.Tests;

[TestClass]
public sealed class TelemetryTests
{
    private static readonly List<TelemetryRecord> s_records = new();

    public static IEnumerable<object[]> Inputs() =>
        InputsLoader.Load().Select(i => new object[] { i });

    [TestMethod]
    [DynamicData(nameof(Inputs), DynamicDataSourceType.Method)]
    public async Task Capture(TelemetryInput input)
    {
        var client = Wire.ResolveAgentClient();

        var messages = new List<ChatMessage> { new(ChatRole.User, input.Text) };
        var sw = Stopwatch.StartNew();
        var response = await client.GetResponseAsync(messages);
        sw.Stop();

        var usage = response.Usage;
        var cost = PriceTable.Cost(
            response.ModelId,
            usage?.InputTokenCount ?? 0,
            usage?.OutputTokenCount ?? 0);

        lock (s_records)
        {
            s_records.Add(new TelemetryRecord(
                AgentName: input.Agent,
                Model: response.ModelId ?? "stub",
                InputTokens: usage?.InputTokenCount ?? 0,
                OutputTokens: usage?.OutputTokenCount ?? 0,
                LatencyMs: sw.ElapsedMilliseconds,
                CostUsd: cost));
        }
    }

    [ClassCleanup]
    public static void WriteReports()
    {
        var outDir = Path.Combine(
            ProjectRoot.Find(), "..", ".copilot", "perf-reports", "evals",
            EvalEnv.ReportFolder);
        Directory.CreateDirectory(outDir);

        var lines = new List<string>
        {
            "# Telemetry Report",
            "",
            $"Generated: {DateTime.UtcNow:O}",
            "",
            "| Agent | Model | Input Tokens | Output Tokens | Latency (ms) | Cost (USD) |",
            "|-------|-------|-------------|--------------|-------------|-----------|"
        };
        foreach (var r in s_records)
            lines.Add($"| {r.AgentName} | {r.Model} | {r.InputTokens} | {r.OutputTokens} | {r.LatencyMs} | ${r.CostUsd:F6} |");

        File.WriteAllLines(Path.Combine(outDir, "telemetry.md"), lines);
        Console.WriteLine($"[Telemetry] {Path.Combine(outDir, "telemetry.md")}");
    }
}

internal record TelemetryRecord(
    string AgentName,
    string Model,
    int InputTokens,
    int OutputTokens,
    long LatencyMs,
    decimal CostUsd);

